pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));
        vm.prank(actor);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        if (ok) {
            // only admin can change owner; owner must equal newOwner only if actor is admin
            assertTrue(actor == address(c.owner()) ? true : true);
        }
        // General rule: after a call by any non-admin actor, owner is unchanged from its initial value (deployer = this contract's address in setUp); admin calls succeed and set owner.
        if (actor != address(this)) {
            assertTrue(ok ? c.owner() == newOwner && actor == address(c) : c.owner() == address(this), "owner changed by non-admin");
        } else {
            assertTrue(c.owner() == newOwner || !ok);
        }
    }
}

