pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address candidate) public {
        // Admissible domain: any address except the current admin/owner is a
        // meaningful "new" owner; keep the domain wide but exclude the case
        // where owner == _owner already trivially makes both versions agree.
        vm.assume(candidate != c.owner());
        vm.assume(candidate != msg.sender);

        // Drive c through setOwner as the admin (constructor-time msg.sender).
        vm.startPrank(msg.sender);
        try c.setOwner(candidate) returns (bool success) {
            vm.stopPrank();
            // General rule: an admin-executed setOwner ALWAYS reports success,
            // regardless of what the previous owner was or who the new owner is.
            assertTrue(success, "admin setOwner must always return true");
        } catch {
            vm.stopPrank();
            assertTrue(false, "admin setOwner must not revert");
        }
    }
}

